def SOURCE_ONLY_time(qualification, payload, scope, review, received, root_binding):
    projected = {k: v for k, v in qualification.items() if k not in {'payload_ref', 'root_issuance_binding_ref', 'schema', 'created_utc'}}
    need(payload.get('schema') == 'researchos.root-main23-runtime-qualification-payload.v2' and {k: v for k, v in payload.items() if k != 'schema'} == projected, 'QUALIFICATION_PAYLOAD_EXACT_BINDING')
    need(when(scope['created_utc']) <= when(review['reviewed_utc']) <= received <= when(qualification['payload_created_utc']) <= when(root_binding['tool_call_timestamp']) <= when(root_binding['tool_result_timestamp']) <= when(qualification['created_utc']) <= datetime.now(timezone.utc), 'RUNTIME_ORIGINAL_REVIEW_ISSUANCE_TIME_ORDER')

def SOURCE_ONLY_peer(payload, expected_refs, peer_actor, operation):
    need(type(peer_actor) is str and re.fullmatch('codex:/root/[a-z0-9_]+', peer_actor) and (peer_actor not in (ROOT, CALLER_AUTHOR, BUILDER_AUTHOR)), 'ACTUAL_NONAUTHOR_PEER_REQUIRED')
    text = payload['content'][0]['text']
    envelope = 'Message Type: FINAL_ANSWER\nTask name: /root\nSender: ' + peer_actor.removeprefix('codex:') + '\nPayload:\n'
    try:
        delivered = strict(text[len(envelope):] if text.startswith(envelope) else text)
    except (ValueError, TypeError):
        need(False, 'PEER_TYPED_DELIVERY_REQUIRED')
    need(type(delivered) is dict and delivered.get('schema') == 'researchos.main23-peer-review-delivery.v2', 'PEER_TYPED_DELIVERY_REQUIRED')
    need(delivered.get('review_author') == peer_actor and delivered.get('root_thread_id') == ROOT_THREAD and (delivered.get('operation') == operation) and (delivered.get('verdict') == 'ACCEPTED_SOURCE_ONLY') and (delivered.get('formal_acceptance') is False) and (delivered.get('execution_grant') is False) and (exact_ref_set(delivered.get('review_refs')) == exact_ref_set(expected_refs)), 'PEER_REVIEW_REF_BINDING')
    return delivered
